    if (!fly) return;
    const b = firstFig.getBoundingClientRect(), a = firstFrame.getBoundingClientRect();
    const s1 = b.top + scrollY + b.height / 2 - innerHeight / 2, p = cl(scrollY / Math.max(1, s1));
    const on = p > .001 && p < .999 && a.width > 0;
