@import url("../tour/tour.css");
/* demo/contact-sheet: the selects. A roll of film contact-printed on one sheet of photographic paper, lying on the
   desk with the photographer's name in the margin. The film's cursor carries a loupe over the frames, sets it down,
   and loops the picks in red grease pencil (an X through a reject). Below the sheet the picks are enlarged, one to a
   screen, on paper, each with its caption; it ends on prints and commissions and one line to write.

   The stage is the desk. Its shape follows the stage (classes tour.js sets before it measures): wide 1600 × 900
   (.demo-contact-sheet), square 960 × 960 (.is-square), tall 680 × 1209 (.is-tall: 9:16 recordings and phones). The
   sheet is always 1040 × 832 sheet px, scaled onto each desk (--ss). Stage geometry comes from container units, so the
   page and the three recording ratios share one set of rules: --fw/--fh/--fx/--fy are the desk's box on the stage,
   --u one design px. */

.demo-contact-sheet{--tour-stage:var(--page);--cs-paper:#fdfcf8;--cs-film:#2a2723;--cs-hole:#151311;--cs-edge:#cfc6b8;--cs-wax:#c62f21;
  --cs-graphite:#6f685e;--cs-ease:cubic-bezier(.2,.7,.2,1);position:relative;background:var(--page)}

/* ── the stage and its desk ──────────────────────────────────────────────────────────────────────────────────── */
.demo-contact-sheet .cs-stage{position:relative;height:100svh;min-height:560px;container-type:size;--dw:1600;--dh:900;
  --fw:min(100cqw,calc(100cqh * var(--dw) / var(--dh)));--fh:calc(var(--fw) * var(--dh) / var(--dw));
  --fx:calc(50cqw - var(--fw) / 2);--fy:calc(50cqh - var(--fh) / 2);--u:calc(var(--fw) / var(--dw))}
@media (max-aspect-ratio:4/5){.demo-contact-sheet .cs-stage{height:min(100svh,calc(100vw * 1209 / 680));min-height:0}}
.demo-contact-sheet.is-square .cs-stage{--dw:960;--dh:960}
.demo-contact-sheet.is-tall .cs-stage{--dw:680;--dh:1209}
.demo-contact-sheet.is-record .cs-stage{min-height:0}
.cs-frame{position:absolute;left:var(--fx);top:var(--fy);width:var(--fw);height:var(--fh);pointer-events:none}
.demo-contact-sheet .cs-win{background:transparent;box-shadow:none;border-radius:0;overflow:visible}
.cs-desk{position:relative;width:100%;height:100%}
/* the arrow steps aside while the hand holds the loupe or the pencil (section.js sets --arrow) */
.demo-contact-sheet .tour-cur svg{opacity:var(--arrow,1)}

/* ── the margin: eyebrow, name, one line, the key to the marks ── */
.cs-margin{position:absolute;left:64px;top:84px;width:360px}
.cs-eyebrow{margin:0;font:500 12px/1 var(--sans);letter-spacing:.18em;text-transform:uppercase;color:var(--ink-3)}
.cs-name{margin:22px 0 0;font:400 78px/.94 var(--serif);letter-spacing:-.032em;color:var(--ink)}
.cs-name em{font-style:italic}
.cs-line{margin:24px 0 0;max-width:330px;font:400 18px/1.45 var(--sans);color:var(--ink-2);text-wrap:pretty}
.cs-key{display:flex;gap:14px;align-items:flex-start;margin:40px 0 0}
.cs-key svg,.cs-cap-n svg{flex:none;width:40px;height:26px;fill:none;stroke:var(--cs-wax);stroke-width:2.4;stroke-linecap:round;opacity:.9}
.cs-key span{display:flex;flex-direction:column;gap:5px}
.cs-key em{font:italic 400 19px/1.2 var(--serif);color:var(--ink)}
.cs-key small{font:400 13.5px/1.35 var(--sans);color:var(--ink-3)}
.demo-contact-sheet.is-square .cs-margin{left:34px;top:784px;width:500px}
.demo-contact-sheet.is-square .cs-margin .cs-eyebrow{margin-bottom:12px}
.demo-contact-sheet.is-square .cs-name{margin:0;font-size:60px}
.demo-contact-sheet.is-square .cs-line{margin:12px 0 0;max-width:480px;font-size:16px}
.demo-contact-sheet.is-square .cs-key{display:none}
.demo-contact-sheet.is-tall .cs-margin{left:40px;top:70px;width:600px}
.demo-contact-sheet.is-tall .cs-name{font-size:84px}
.demo-contact-sheet.is-tall .cs-line{max-width:520px;font-size:22px}
.demo-contact-sheet.is-tall .cs-key{display:none}

/* ── the sheet: glossy fibre-white paper, the roll's strips printed on it, a pencilled note at the top ── */
.cs-sheet{position:absolute;left:494px;top:34px;width:1040px;height:832px;padding:50px 36px 0;transform-origin:0 0;transform:scale(var(--ss,1));
  background:var(--cs-paper);border-radius:1.5px;
  box-shadow:0 0 0 1px rgba(25,24,22,.05),0 1px 2px rgba(25,24,22,.06),0 22px 44px -26px rgba(25,24,22,.32),0 60px 100px -70px rgba(25,24,22,.4)}
