  -webkit-mask:radial-gradient(circle,transparent calc(50% - 10px),#000 calc(50% - 9.5px));mask:radial-gradient(circle,transparent calc(50% - 10px),#000 calc(50% - 9.5px))}

/* the china marker the hand picks up to mark */
.cs-pencil{position:absolute;left:0;top:0;z-index:6;width:0;height:0;opacity:0;pointer-events:none;transform-origin:0 0}
