.demo-contact-sheet.is-tall .cs-pencil svg{width:52px;height:97px}

/* ── ?record: the selects enlarged onto paper, one to a page (built by section.js from .cs-seq) ── */
.cs-prints{--paper:0;--page:0;position:absolute;inset:0;z-index:8;overflow:hidden;pointer-events:none;background:rgba(245,243,239,var(--paper))}
.cs-pr{--lift:1;position:absolute;inset:0;opacity:min(1,calc(var(--paper) * 3));display:flex;flex-direction:column;align-items:center;justify-content:center;gap:24px;
  transform:translateY(calc((var(--i) - var(--page)) * 100%))}
.cs-pr .cs-print{width:870px;transform-origin:0 0;
  transform:translate(calc(var(--dx,0) * (1 - var(--lift)) * 1px),calc(var(--dy,0) * (1 - var(--lift)) * 1px)) scale(calc(1 + (var(--ds,1) - 1) * (1 - var(--lift))));
  box-shadow:0 0 0 1px rgba(25,24,22,.05),0 calc(30px * var(--lift)) calc(60px * var(--lift)) calc(-34px * var(--lift)) rgba(25,24,22,.4)}
.cs-pr .cs-print{padding:calc(14px * var(--lift))}
.cs-pr.is-portrait .cs-print{width:430px}
.cs-pr .cs-cap{width:870px;opacity:calc((var(--lift) - .55) * 2.3)}
.cs-pr.is-portrait .cs-cap{width:430px}
.demo-contact-sheet.is-square .cs-pr .cs-print,.demo-contact-sheet.is-square .cs-pr .cs-cap{width:820px}
.demo-contact-sheet.is-square .cs-pr.is-portrait .cs-print,.demo-contact-sheet.is-square .cs-pr.is-portrait .cs-cap{width:440px}
.demo-contact-sheet.is-tall .cs-pr .cs-print,.demo-contact-sheet.is-tall .cs-pr .cs-cap{width:600px}
.cs-pr .cs-cap{font-size:1.15em}
.demo-contact-sheet:not(.is-square,.is-tall) .cs-pr{padding-left:400px}     /* the wide desk keeps its margin for the card */
.demo-contact-sheet.is-tall .cs-pr{bottom:300px;transform:translateY(calc((var(--i) - var(--page)) * 1240px))}     /* the tall desk keeps its foot for the card */
.demo-contact-sheet.is-tall .cs-pr.is-portrait .cs-print,.demo-contact-sheet.is-tall .cs-pr.is-portrait .cs-cap{width:400px}

/* ── overlays on the stage: the chapter card as an index card in the desk's margin, the caption, the closing frame ── */
.demo-contact-sheet .tour-card,.demo-contact-sheet.is-stack .tour-card{left:calc(var(--fx) + 64 * var(--u));right:auto;top:auto;bottom:calc(100cqh - var(--fy) - 866 * var(--u));
  width:calc(330 * var(--u));padding:calc(20 * var(--u)) calc(22 * var(--u)) calc(22 * var(--u));border-radius:calc(2 * var(--u));background:var(--cs-paper);
  box-shadow:0 0 0 1px rgba(25,24,22,.06),0 calc(14 * var(--u)) calc(30 * var(--u)) calc(-18 * var(--u)) rgba(25,24,22,.3);border-top:calc(2 * var(--u)) solid var(--cs-wax)}
.demo-contact-sheet .tour-card-x{display:none}
.demo-contact-sheet .tour-card-n{font:500 max(9px,calc(11 * var(--u)))/1 var(--sans);letter-spacing:.17em;color:var(--ink-3)}
.demo-contact-sheet .tour-card h3{margin:calc(12 * var(--u)) 0 calc(9 * var(--u));font:400 max(19px,calc(34 * var(--u)))/1.02 var(--serif);letter-spacing:-.02em}
.demo-contact-sheet .tour-card p{font:400 max(12px,calc(14.5 * var(--u)))/1.45 var(--sans);color:var(--ink-2)}
.demo-contact-sheet.is-square .tour-card{left:calc(var(--fx) + 556 * var(--u));top:auto;bottom:calc(100cqh - var(--fy) - 940 * var(--u));width:calc(370 * var(--u));padding:calc(16 * var(--u)) calc(20 * var(--u)) calc(18 * var(--u))}
.demo-contact-sheet.is-square .tour-card h3{font-size:max(17px,calc(30 * var(--u)))}
.demo-contact-sheet.is-tall .tour-card{left:calc(var(--fx) + 40 * var(--u));top:calc(var(--fy) + 962 * var(--u));bottom:auto;width:calc(600 * var(--u));padding:calc(20 * var(--u)) calc(24 * var(--u))}
.demo-contact-sheet.is-tall .tour-card h3{font-size:max(19px,calc(40 * var(--u)))}
.demo-contact-sheet.is-tall .tour-card p{font-size:max(12px,calc(17 * var(--u)))}

.demo-contact-sheet .tour-cap{left:calc(var(--fx) + 64 * var(--u));bottom:calc(100cqh - var(--fy) - 650 * var(--u));max-width:calc(360 * var(--u));text-align:left;
  transform:translate(0,calc((1 - var(--o,0)) * 8px));font-size:max(13px,calc(18 * var(--u)));padding:calc(10 * var(--u)) calc(16 * var(--u))}
.demo-contact-sheet.is-square .tour-cap{left:50%;bottom:auto;top:calc(var(--fy) + 22 * var(--u));transform:translate(-50%,calc((1 - var(--o,0)) * 8px));max-width:calc(700 * var(--u));text-align:center;font-size:calc(20 * var(--u))}
.demo-contact-sheet.is-stack.is-tall .tour-cap{top:auto;left:calc(var(--fx) + 40 * var(--u));bottom:calc(100cqh - var(--fy) - 1192 * var(--u));max-width:calc(600 * var(--u));font-size:calc(22 * var(--u))}

.cs-end-frame{position:absolute;z-index:9;left:var(--fx);top:var(--fy);width:var(--fw);height:var(--fh);margin:0;display:flex;flex-direction:column;justify-content:center;
  padding:0 calc(220 * var(--u));background:var(--page);opacity:var(--in,0);pointer-events:none}
