.cs-end-frame .cs-eyebrow{font-size:calc(14 * var(--u))}
.cs-end-frame .cs-end-h{margin-top:calc(26 * var(--u));font:400 calc(78 * var(--u))/1 var(--serif);letter-spacing:-.03em;color:var(--ink);
  transform:translateY(calc((1 - var(--in,0)) * 16 * var(--u)))}
.cs-end-frame .cs-end-h em{font-style:italic}
.cs-end-mail{margin-top:calc(46 * var(--u))!important;padding-top:calc(24 * var(--u));border-top:1px solid var(--rule);font:italic 400 calc(34 * var(--u))/1.1 var(--serif);color:var(--ink)}
.cs-end-site{margin-top:calc(10 * var(--u))!important;font:400 calc(17 * var(--u))/1.3 var(--sans);color:var(--ink-2)}
.demo-contact-sheet.is-square .cs-end-frame{padding:0 calc(80 * var(--u))}
