.demo-contact-sheet:not(.is-record) .cs-end-frame{display:none}

/* the page's control: watch the edit, skip it; then the way down to the selects */
.cs-ctl{position:absolute;z-index:9;left:calc(var(--fx) + 64 * var(--u));top:calc(var(--fy) + 448 * var(--u));display:flex;flex-direction:column;align-items:flex-start;gap:12px}
.cs-ctl-btn{display:inline-flex;align-items:center;gap:10px;height:34px;padding:0 15px 0 13px;border:0;border-radius:17px;background:rgba(253,252,248,.92);
  box-shadow:0 0 0 1px rgba(25,24,22,.08),0 6px 16px -10px rgba(25,24,22,.35);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);
  font:500 13px/1 var(--sans);color:var(--ink);cursor:pointer}
.cs-ctl-btn svg{width:9px;height:9px;fill:currentColor;stroke:currentColor;stroke-width:1;stroke-linejoin:round}
.cs-ctl-btn .i-skip{display:none}
